import { Ability, abilityModifier, rollDice } from '../data/gameData';
import { Vector2 } from '../engine/types';
import {
  ActiveCondition,
  AttackOpts,
  BOSS_KITS,
  ConditionId,
  applyCondition,
  hasCondition,
  removeCondition,
  rollD20,
} from '../rules/Rules';
import { DiceType, pushDiceRoll } from '../rules/DiceEvents';

export interface MonsterTemplate {
  id: string;
  name: string;
  description: string;
  hp: number;
  ac: number;
  speed: number;
  abilities: Record<Ability, number>;
  attackBonus: number;
  damageDie: number;
  damageDice: number;
  damageBonus: number;
  xp: number;
  cr: number;
  size: 'Small' | 'Medium' | 'Large';
  type: 'beast' | 'undead' | 'humanoid' | 'dragon' | 'aberration' | 'fiend' | 'giant' | 'monstrosity' | 'ooze' | 'construct' | 'fey' | 'celestial' | 'plant' | 'elemental';
}

export class Monster {
  public id: string;
  public template: MonsterTemplate;
  public tile: Vector2;
  public hp: number;
  public maxHp: number;
  public isAlive: boolean = true;
  public alertLevel: number = 0; // 0 = unaware, 1 = suspicious, 2 = hostile
  public patrolPoints: Vector2[] = [];
  public patrolIndex: number = 0;

  // Visual state for animations
  public flashTimer: number = 0;

  // Active rules-layer conditions (paralyzed, unconscious, poisoned...)
  public conditions: ActiveCondition[] = [];

  /** Legendary actions left this round (boss fights) — regained at the start of the boss's turn. */
  public legendaryActions: number = 0;

  /** 5e legendary resistances remaining (turned a failed save into a success). */
  public legendaryResistances: number = 0;

  /** Whether this lycanthrope has shed its skin under the full moon. */
  public moonTransformed: boolean = false;

  /** True when this beast was part of a full-moon hunting pack (drops moon trophies). */
  public moonPack: boolean = false;

  /** True when this gloom-spawned undead carries a torn half of a rune tablet. */
  public dropsRuneHalf: boolean = false;
  private moonHowlHp: number = 0;
  private moonHowlAttack: number = 0;
  private moonHowlDamage: number = 0;

  /**
   * Try to spend a legendary resistance to turn a failed save into a success.
   * Returns true when a resistance was burned (caller should flip the result).
   */
  spendLegendaryResistance(): boolean {
    if (this.legendaryResistances <= 0) return false;
    this.legendaryResistances -= 1;
    return true;
  }

  constructor(id: string, template: MonsterTemplate, tile: Vector2) {
    this.id = id;
    this.template = template;
    this.tile = { ...tile };
    this.maxHp = template.hp;
    this.hp = template.hp;
  }

  get name(): string { return this.template.name; }
  get ac(): number { return this.template.ac; }
  /** Damage die while moon-touched (transformed claws bite deeper). */
  get damageDie(): number { return this.template.damageDie; }
  get damageDice(): number {
    return this.template.damageDice + (this.moonTransformed ? this.moonHowlDamage : 0);
  }
  get attackBonus(): number {
    return this.template.attackBonus + (this.moonTransformed ? this.moonHowlAttack : 0);
  }

  /**
   * Under the full moon a lycanthrope sheds its human covering — it bubbles,
   * grows talons, pours strength into furred sinew. Boosts max HP (spent
   * immediately), attack bonus, and damage dice for the fight.
   */
  awakenMoonHowl(): string {
    if (this.moonTransformed) return '';
    this.moonTransformed = true;
    this.moonHowlHp = Math.max(1, Math.round(this.template.hp * 0.35));
    this.moonHowlAttack = 2;
    this.moonHowlDamage = 1;
    this.maxHp = this.template.hp + this.moonHowlHp;
    this.hp = Math.min(this.maxHp, this.hp + this.moonHowlHp);
    return `The full moon rips the veil from ${this.template.name} \u2014 fur tears through skin as it howls and swells with +${this.moonHowlHp} HP!`;
  }

  /** True when this monster has a boss kit (legendary / lair actions). */
  get isBoss(): boolean { return BOSS_KITS[this.template.id] !== undefined; }

  takeDamage(amount: number, opts?: { crit?: boolean }): string {
    const messages: string[] = [];
    // Damage wakes a sleeping monster.
    if (removeCondition(this, 'unconscious')) {
      messages.push(`${this.template.name} snaps awake!`);
    }
    this.hp -= amount;
    this.flashTimer = 0.3;
    this.alertLevel = 2;
    if (this.hp <= 0) {
      this.hp = 0;
      this.isAlive = false;
      messages.push(`${this.template.name} is slain!`);
      return messages.join(' ');
    }
    // The crit marker rides on the damage line itself so presentation layers
    // (battle window pops, sparks) can detect it without parsing narration.
    messages.push(`${this.template.name} takes ${amount} damage.${opts?.crit ? ' CRITICAL!' : ''}`);
    return messages.join(' ');
  }

  applyCondition(id: ConditionId, turnsLeft: number, name: string, sourceId?: string): boolean {
    return applyCondition(this, { id, name, turnsLeft, sourceId });
  }

  hasCondition(id: ConditionId): boolean {
    return hasCondition(this, id);
  }

  attack(targetAc: number, opts?: AttackOpts): { hit: boolean; damage: number; message: string } {
    const advantage = Boolean(opts?.advantage && !opts.disadvantage);
    const disadvantage = Boolean(opts?.disadvantage);
    const rolls = [rollD20()];
    if (advantage || disadvantage) rolls.push(rollD20());
    const roll = advantage ? Math.max(...rolls) : disadvantage ? Math.min(...rolls) : rolls[0];
    const total = roll + this.attackBonus;

    pushDiceRoll({
      kind: 'attack',
      diceType: 'd20',
      label: `${this.template.name} attacks (AC ${targetAc})`,
      expression: `${advantage ? '2d20-adv' : disadvantage ? '2d20-dis' : 'd20'}${this.attackBonus >= 0 ? '+' : ''}${this.attackBonus}`,
      rolls,
      total,
      outcome: roll === 20 ? 'crit' : roll === 1 ? 'fumble' : total >= targetAc ? 'success' : 'failure',
    });

    if (roll === 20) {
      const damage = rollDice(this.damageDice * 2, this.damageDie) + this.template.damageBonus;
      pushDiceRoll({
        kind: 'damage',
        diceType: 'd' + this.damageDie as DiceType,
        label: `${this.template.name} critical hits`,
        expression: `${this.damageDice * 2}d${this.damageDie}${this.template.damageBonus >= 0 ? '+' : ''}${this.template.damageBonus}`,
        rolls: [damage],
        total: damage,
        outcome: 'crit',
      });
      return { hit: true, damage, message: `CRIT! ${this.template.name} deals ${damage} damage!` };
    }

    if (total >= targetAc) {
      const damage = rollDice(this.damageDice, this.damageDie) + this.template.damageBonus;
      pushDiceRoll({
        kind: 'damage',
        diceType: 'd' + this.damageDie as DiceType,
        label: `${this.template.name} hits`,
        expression: `${this.damageDice}d${this.damageDie}${this.template.damageBonus >= 0 ? '+' : ''}${this.template.damageBonus}`,
        rolls: [damage],
        total: damage,
        outcome: 'neutral',
      });
      return { hit: true, damage, message: `${this.template.name} attacks for ${damage} damage.` };
    }

    return { hit: false, damage: 0, message: `${this.template.name} misses.` };
  }
}

