export function getMonsterTemplate(id: string): MonsterTemplate | undefined {
  return MONSTER_TEMPLATES.find(m => m.id === id);
}

export function getMonstersByCr(maxCr: number): MonsterTemplate[] {
  return MONSTER_TEMPLATES.filter(m => m.cr <= maxCr && !isUnseeableMonster(m.id));
}

/**
 * Monster kinds the party should never silently run into: creatures that are
 * invisible or effectively unseeable by nature. The player asked that the
 * team never fight things they can't see, so these are excluded from every
 * spawn path (generic pool, theme rosters, and boss picks filter through
 * this too).
 */
export function isUnseeableMonster(id: string): boolean {
  switch (id) {
    case 'invisible_stalker':
      return true;
    default:
      return false;
  }
}

