/**
 * Pick a random monster at or below maxCr. When a dungeon theme is given,
 * ~3/4 of picks come from the theme's affinity list (CR-permitting); the rest
 * stay generic so every delve keeps a hint of the unexpected.
 */
export function getRandomMonster(maxCr: number, themeId?: string): MonsterTemplate {
  const generic = getMonstersByCr(maxCr);
  if (generic.length === 0) return MONSTER_TEMPLATES[0];
  if (themeId) {
    const affinity = THEME_MONSTERS[themeId];
    const themed = affinity ? generic.filter(m => affinity.includes(m.id)) : [];
    if (themed.length > 0 && Math.random() < 0.75) {
      return themed[Math.floor(Math.random() * themed.length)];
    }
  }
  return generic[Math.floor(Math.random() * generic.length)];
}